SELECT pu.id, pu.package_id AS packageId, pu.user_id AS userId, pu.tenant_id AS tenantId, u.phone, u.nick_name AS nickName, pu.update_date AS updateDate, pu.create_date AS createDate FROM tb_package_user pu LEFT JOIN tb_user u ON pu.user_id = u.id WHERE pu.is_deleted = 0 AND pu.package_id = #{packageId}
AND (u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY pu.create_date DESC
